import React, { useState, useEffect } from 'react';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

function ProviderDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [services, setServices] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [earnings, setEarnings] = useState({ totalRevenue: 0, totalEarnings: 0, platformFees: 0, totalBookings: 0 });
  const [pendingPayout, setPendingPayout] = useState(0);
  const [payoutHistory, setPayoutHistory] = useState([]);
  const [pendingPayoutAmount, setPendingPayoutAmount] = useState(0);
  const [pendingPayoutCount, setPendingPayoutCount] = useState(0);
  const [recentPayments, setRecentPayments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadingPayouts, setLoadingPayouts] = useState(false);
  const [showPayoutModal, setShowPayoutModal] = useState(false);
  const [showServiceModal, setShowServiceModal] = useState(false);
  const [editingService, setEditingService] = useState(null);
  const [payoutAmount, setPayoutAmount] = useState('');
  const [showEditProfileModal, setShowEditProfileModal] = useState(false);
  const [showBankModal, setShowBankModal] = useState(false);
  const [hasBankAccount, setHasBankAccount] = useState(false);
  const [loadingBank, setLoadingBank] = useState(false);
  const [loadingStripe, setLoadingStripe] = useState(false);
  const [stripeStatus, setStripeStatus] = useState({ hasAccount: false, status: null, onboardingComplete: false });

  const [bankAccount, setBankAccount] = useState({
    accountName: '',
    accountNumber: '',
    bankName: '',
    routingNumber: ''
  });

  const [settings, setSettings] = useState({
    emailNotifications: true,
    pushNotifications: true,
    smsNotifications: false,
    autoConfirm: false,
    priceAlerts: true,
    calendarSync: false,
    language: 'english'
  });

  const [notifications, setNotifications] = useState([
    { id: 1, type: 'booking', title: 'New Booking', message: 'John Doe booked Oil Change', time: '2 hours ago', read: false, icon: '📅' },
    { id: 2, type: 'payment', title: 'Payment Received', message: '$49.99 received for Oil Change', time: '1 day ago', read: true, icon: '💰' },
    { id: 3, type: 'review', title: 'New Review', message: 'Customer left a 5-star review', time: '3 days ago', read: false, icon: '⭐' }
  ]);

  const [businessProfile, setBusinessProfile] = useState({
    businessName: user?.businessName || '',
    ownerName: `${user?.firstName || ''} ${user?.lastName || ''}`,
    email: user?.email || '',
    phone: user?.phone || '',
    address: user?.businessAddress || '',
    taxId: user?.businessLicense || '',
    logo: user?.profilePicture || `https://ui-avatars.com/api/?background=10b981&color=fff&name=${user?.businessName?.charAt(0) || 'P'}`
  });

  const [editProfileData, setEditProfileData] = useState({
    businessName: businessProfile.businessName,
    ownerName: businessProfile.ownerName,
    email: businessProfile.email,
    phone: businessProfile.phone,
    address: businessProfile.address,
    taxId: businessProfile.taxId
  });

  const [serviceForm, setServiceForm] = useState({
    name: '', description: '', category: 'oil-change', price: '', duration: '30',
    discountedPrice: '', warranty: '', tags: '', requirements: '', inclusions: ''
  });

  const categories = [
    { id: 'oil-change', name: 'Oil Change', icon: '🛢️' },
    { id: 'brake-repair', name: 'Brake Repair', icon: '🛑' },
    { id: 'tire-service', name: 'Tire Service', icon: '🛞' },
    { id: 'engine-repair', name: 'Engine Repair', icon: '🔧' },
    { id: 'ac-repair', name: 'AC Repair', icon: '❄️' },
    { id: 'transmission', name: 'Transmission', icon: '⚙️' },
    { id: 'detailing', name: 'Detailing', icon: '🧼' },
    { id: 'maintenance', name: 'Maintenance', icon: '📋' },
    { id: 'electrical', name: 'Electrical', icon: '⚡' },
    { id: 'body-repair', name: 'Body Repair', icon: '🚘' }
  ];

  const token = localStorage.getItem('token');

  // WORKING INVOICE DOWNLOAD FUNCTION
  const downloadInvoice = async (paymentId) => {
    if (!paymentId) {
      toast.error('No payment ID available');
      return;
    }
    try {
      const res = await fetch(`http://localhost:5000/api/invoices/download/${paymentId}`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (res.ok) {
        const blob = await res.blob();
        const url = window.URL.createObjectURL(blob);
        window.open(url, '_blank');
        setTimeout(() => window.URL.revokeObjectURL(url), 100);
        toast.success('Invoice opened in new tab');
      } else {
        toast.error('Failed to download invoice: ' + res.status);
      }
    } catch (err) {
      toast.error('Error downloading invoice');
    }
  };

  useEffect(() => {
    fetchAllData();
    fetchBankAccount();
    checkStripeStatus();
  }, []);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      await Promise.all([
        fetchServices(),
        fetchBookings(),
        fetchEarnings(),
        fetchPayoutHistory()
      ]);
    } catch (error) {
      console.error('Error fetching data:', error);
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const fetchServices = async () => {
    const res = await fetch('http://localhost:5000/api/services/provider/my-services', {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    const data = await res.json();
    if (data.success) setServices(data.services);
  };

  const fetchBookings = async () => {
    const res = await fetch('http://localhost:5000/api/services/provider/bookings', {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    const data = await res.json();
    if (data.success) setBookings(data.bookings);
  };

  const fetchEarnings = async () => {
    const res = await fetch('http://localhost:5000/api/payments/provider/earnings', {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    const data = await res.json();
    if (data.success) {
      setEarnings(data.earnings);
      setPendingPayout(data.pendingPayout || 0);
      setRecentPayments(data.recentPayments || []);
    }
  };

  const fetchPayoutHistory = async () => {
    setLoadingPayouts(true);
    try {
      const res = await fetch('http://localhost:5000/api/payments/provider/payout-history', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) {
        setPayoutHistory(data.payoutHistory || []);
        setPendingPayoutAmount(data.pendingAmount || 0);
        setPendingPayoutCount(data.pendingCount || 0);
      }
    } catch (error) {
      console.error('Error fetching payout history:', error);
    } finally {
      setLoadingPayouts(false);
    }
  };

  const fetchBankAccount = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/provider/bank-account', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success && data.bankAccount) {
        setBankAccount(data.bankAccount);
        setHasBankAccount(true);
      }
    } catch (error) {
      console.error('Error fetching bank account:', error);
    }
  };

  const saveBankAccount = async (e) => {
    e.preventDefault();
    setLoadingBank(true);
    try {
      const res = await fetch('http://localhost:5000/api/provider/bank-account', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(bankAccount)
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Bank account saved successfully!');
        setHasBankAccount(true);
        setShowBankModal(false);
      } else {
        toast.error(data.error || 'Failed to save bank account');
      }
    } catch (error) {
      toast.error('Failed to save bank account');
    } finally {
      setLoadingBank(false);
    }
  };

  const deleteBankAccount = async () => {
    if (window.confirm('Are you sure you want to remove your bank account details?')) {
      try {
        const res = await fetch('http://localhost:5000/api/provider/bank-account', {
          method: 'DELETE',
          headers: { 'Authorization': `Bearer ${token}` }
        });
        const data = await res.json();
        if (data.success) {
          toast.success('Bank account removed');
          setHasBankAccount(false);
          setBankAccount({ accountName: '', accountNumber: '', bankName: '', routingNumber: '' });
        }
      } catch (error) {
        toast.error('Failed to remove bank account');
      }
    }
  };

  const checkStripeStatus = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/stripe/account-status', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      setStripeStatus(data);
    } catch (error) {
      console.error('Error checking Stripe status:', error);
    }
  };

  const connectStripe = async () => {
    setLoadingStripe(true);
    try {
      const res = await fetch('http://localhost:5000/api/stripe/onboarding-link', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success && data.url) {
        window.location.href = data.url;
      } else {
        toast.error('Failed to create Stripe connection link');
      }
    } catch (error) {
      toast.error('Failed to connect Stripe');
    } finally {
      setLoadingStripe(false);
    }
  };

  const disconnectStripe = async () => {
    if (window.confirm('Are you sure you want to disconnect your Stripe account?')) {
      try {
        const res = await fetch('http://localhost:5000/api/stripe/disconnect', {
          method: 'POST',
          headers: { 'Authorization': `Bearer ${token}` }
        });
        const data = await res.json();
        if (data.success) {
          toast.success('Stripe account disconnected');
          checkStripeStatus();
        }
      } catch (error) {
        toast.error('Failed to disconnect Stripe');
      }
    }
  };

  const updateProfile = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch('http://localhost:5000/api/provider/business-profile', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          businessName: editProfileData.businessName,
          businessAddress: editProfileData.address,
          businessLicense: editProfileData.taxId,
          phone: editProfileData.phone
        })
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Profile updated successfully!');
        setBusinessProfile({
          ...businessProfile,
          businessName: editProfileData.businessName,
          ownerName: editProfileData.ownerName,
          email: editProfileData.email,
          phone: editProfileData.phone,
          address: editProfileData.address,
          taxId: editProfileData.taxId
        });
        setShowEditProfileModal(false);
      } else {
        toast.error(data.error || 'Failed to update profile');
      }
    } catch (error) {
      toast.error('Failed to update profile');
    }
  };

  const handleServiceSubmit = async (e) => {
    e.preventDefault();
    try {
      const payload = {
        ...serviceForm,
        price: parseFloat(serviceForm.price),
        duration: parseInt(serviceForm.duration),
        discountedPrice: serviceForm.discountedPrice ? parseFloat(serviceForm.discountedPrice) : undefined,
        tags: serviceForm.tags.split(',').map(t => t.trim()),
        requirements: serviceForm.requirements.split(',').map(r => r.trim()),
        inclusions: serviceForm.inclusions.split(',').map(i => i.trim())
      };

      let url = 'http://localhost:5000/api/services';
      let method = 'POST';

      if (editingService) {
        url = `http://localhost:5000/api/services/${editingService._id}`;
        method = 'PUT';
      }

      const res = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(payload)
      });
      const data = await res.json();
      if (data.success) {
        toast.success(editingService ? 'Service updated!' : 'Service added!');
        setShowServiceModal(false);
        setEditingService(null);
        setServiceForm({ name: '', description: '', category: 'oil-change', price: '', duration: '30', discountedPrice: '', warranty: '', tags: '', requirements: '', inclusions: '' });
        fetchServices();
      }
    } catch (error) {
      toast.error('Failed to save service');
    }
  };

  const handleDeleteService = async (serviceId) => {
    if (window.confirm('Are you sure you want to delete this service?')) {
      try {
        const res = await fetch(`http://localhost:5000/api/services/${serviceId}`, {
          method: 'DELETE',
          headers: { 'Authorization': `Bearer ${token}` }
        });
        const data = await res.json();
        if (data.success) {
          toast.success('Service deleted!');
          fetchServices();
        }
      } catch (error) {
        toast.error('Failed to delete service');
      }
    }
  };

  const handleToggleStatus = async (serviceId) => {
    try {
      const res = await fetch(`http://localhost:5000/api/services/${serviceId}/toggle-status`, {
        method: 'PATCH',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`Service ${data.service.isActive ? 'activated' : 'deactivated'}`);
        fetchServices();
      }
    } catch (error) {
      toast.error('Failed to update status');
    }
  };

  const updateBookingStatus = async (bookingId, status) => {
    try {
      const res = await fetch(`http://localhost:5000/api/services/provider/bookings/${bookingId}/status`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ status })
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`Booking ${status}!`);
        fetchBookings();
      }
    } catch (error) {
      toast.error('Failed to update booking');
    }
  };

  const editService = (service) => {
    setEditingService(service);
    setServiceForm({
      name: service.name,
      description: service.description,
      category: service.category,
      price: service.price,
      duration: service.duration,
      discountedPrice: service.discountedPrice || '',
      warranty: service.warranty || '',
      tags: (service.tags || []).join(', '),
      requirements: (service.requirements || []).join(', '),
      inclusions: (service.inclusions || []).join(', ')
    });
    setShowServiceModal(true);
  };

  const requestPayout = async () => {
    if (!payoutAmount || parseFloat(payoutAmount) <= 0) {
      toast.error('Please enter a valid amount');
      return;
    }
    if (parseFloat(payoutAmount) > pendingPayoutAmount) {
      toast.error('Amount exceeds available balance');
      return;
    }

    try {
      const res = await fetch('http://localhost:5000/api/payments/provider/payout', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ amount: parseFloat(payoutAmount) })
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Payout request submitted!');
        setShowPayoutModal(false);
        setPayoutAmount('');
        fetchEarnings();
        fetchPayoutHistory();
      } else {
        toast.error(data.error);
      }
    } catch (error) {
      toast.error('Failed to request payout');
    }
  };

  const getStatusBadge = (status) => {
    const colors = {
      pending: '#f59e0b',
      confirmed: '#10b981',
      'in-progress': '#3b82f6',
      completed: '#8b5cf6',
      cancelled: '#ef4444'
    };
    return { backgroundColor: colors[status] || '#6b7280', color: 'white', padding: '4px 12px', borderRadius: '20px', fontSize: '12px', display: 'inline-block' };
  };

  const totalRevenue = earnings.totalRevenue || 0;
  const yourEarnings = earnings.totalEarnings || 0;
  const platformFees = earnings.platformFees || 0;
  const completedBookings = earnings.totalBookings || 0;
  const pendingBookings = bookings.filter(b => b.status === 'pending').length;
  const firstPaymentId = recentPayments.length > 0 ? recentPayments[0]._id : null;

  return (
    <div style={styles.dashboard}>
      <ToastContainer position="top-right" />

      <div style={styles.header}>
        <div style={styles.logoSection}>
          <span style={styles.logoIcon}>🔧</span>
          <h1 style={styles.logoText}>Car Care Connect - Provider</h1>
        </div>
        <div style={styles.userInfo}>
          <span>🔧 {user?.businessName || user?.firstName}</span>
          <button onClick={onLogout} style={styles.logoutButton}>Logout</button>
        </div>
      </div>

      <div style={styles.statsGrid}>
        <div style={styles.statCard}><h3>💰 Total Revenue</h3><p style={styles.statNumber}>${totalRevenue.toLocaleString()}</p></div>
        <div style={styles.statCard}><h3>💵 Your Earnings</h3><p style={styles.statNumber}>${yourEarnings.toLocaleString()}</p></div>
        <div style={styles.statCard}><h3>📊 Platform Fee</h3><p style={styles.statNumber}>${platformFees.toLocaleString()}</p></div>
        <div style={styles.statCard}><h3>📅 Completed</h3><p style={styles.statNumber}>{completedBookings}</p></div>
        <div style={styles.statCard}><h3>⏳ Pending</h3><p style={styles.statNumber}>{pendingBookings}</p></div>
        <div style={styles.statCard}><h3>💰 Pending Payout</h3><p style={styles.statNumber}>${pendingPayoutAmount.toLocaleString()}</p><button style={styles.payoutBtn} onClick={() => setShowPayoutModal(true)}>Request</button></div>
      </div>

      <div style={styles.tabs}>
        <button style={{...styles.tab, ...(activeTab === 'dashboard' ? styles.activeTab : {})}} onClick={() => setActiveTab('dashboard')}>📊 Dashboard</button>
        <button style={{...styles.tab, ...(activeTab === 'services' ? styles.activeTab : {})}} onClick={() => setActiveTab('services')}>🛠️ Services</button>
        <button style={{...styles.tab, ...(activeTab === 'bookings' ? styles.activeTab : {})}} onClick={() => setActiveTab('bookings')}>📅 Bookings</button>
        <button style={{...styles.tab, ...(activeTab === 'earnings' ? styles.activeTab : {})}} onClick={() => setActiveTab('earnings')}>💰 Earnings</button>
        <button style={{...styles.tab, ...(activeTab === 'notifications' ? styles.activeTab : {})}} onClick={() => setActiveTab('notifications')}>🔔 Notifications</button>
        <button style={{...styles.tab, ...(activeTab === 'profile' ? styles.activeTab : {})}} onClick={() => setActiveTab('profile')}>👤 Profile</button>
        <button style={{...styles.tab, ...(activeTab === 'settings' ? styles.activeTab : {})}} onClick={() => setActiveTab('settings')}>⚙️ Settings</button>
      </div>

      <div style={styles.content}>
        {loading ? <div style={styles.loading}>Loading...</div> : (
          <>
            {activeTab === 'dashboard' && (
              <div style={styles.twoColumn}>
                <div><div style={styles.card}><h3>📈 Recent Activity</h3>{bookings.slice(0, 5).map(booking => (<div key={booking._id} style={styles.activityItem}><span>{booking.serviceName} - {booking.customerId?.firstName}</span><span style={getStatusBadge(booking.status)}>{booking.status}</span></div>))}</div></div>
                <div><div style={styles.card}><h3>💰 Recent Payments</h3>{recentPayments.map(payment => (<div key={payment._id} style={styles.paymentItem}><span>{payment.bookingId?.serviceName}</span><span>${payment.amount}</span><span style={{ color: '#10b981' }}>+${payment.providerEarnings}</span><button onClick={() => downloadInvoice(payment._id)} style={styles.invoiceBtn}>📄 Invoice</button></div>))}</div><div style={styles.card}><h3>📦 Quick Actions</h3><button style={styles.actionBtn} onClick={() => setActiveTab('services')}>➕ Add Service</button><button style={styles.actionBtn} onClick={() => setActiveTab('bookings')}>📅 View Bookings</button></div></div>
              </div>
            )}

            {activeTab === 'services' && (
              <div><button style={styles.addBtn} onClick={() => { setEditingService(null); setServiceForm({ name: '', description: '', category: 'oil-change', price: '', duration: '30', discountedPrice: '', warranty: '', tags: '', requirements: '', inclusions: '' }); setShowServiceModal(true); }}>+ Add Service</button>
              <div style={styles.servicesGrid}>{services.map(service => {
                const serviceBookings = bookings.filter(b => b.serviceId === service._id);
                const serviceRevenue = serviceBookings.filter(b => b.status === 'completed').reduce((sum, b) => sum + (b.totalAmount || 0), 0);
                return (<div key={service._id} style={styles.serviceCard}><div style={styles.serviceHeader}><h3>{service.name}</h3><span style={{ backgroundColor: service.isActive ? '#d1fae5' : '#fee2e2', color: service.isActive ? '#065f46' : '#991b1b', padding: '4px 8px', borderRadius: '20px', fontSize: '11px' }}>{service.isActive ? 'Active' : 'Inactive'}</span></div><p style={styles.serviceDesc}>{service.description?.substring(0, 80)}...</p><div style={styles.serviceDetails}><span>{categories.find(c => c.id === service.category)?.icon} {service.category}</span><span>💰 ${service.price}</span><span>⏱️ {service.duration} min</span></div><div style={styles.serviceStats}><span>📊 {serviceBookings.length} bookings</span><span>💰 ${serviceRevenue} revenue</span></div><div style={styles.serviceActions}><button style={styles.editBtn} onClick={() => editService(service)}>✏️ Edit</button><button style={styles.toggleBtn} onClick={() => handleToggleStatus(service._id)}>{service.isActive ? '🔴 Deactivate' : '🟢 Activate'}</button><button style={styles.deleteBtn} onClick={() => handleDeleteService(service._id)}>🗑️ Delete</button></div></div>);
              })}</div></div>
            )}

            {activeTab === 'bookings' && (
              <div>{bookings.map(booking => (<div key={booking._id} style={styles.bookingCard}><div style={styles.bookingHeader}><div><h3>{booking.serviceName}</h3><p><strong>Customer:</strong> {booking.customerId?.firstName} {booking.customerId?.lastName}</p><p><strong>Phone:</strong> {booking.customerId?.phone}</p></div><span style={getStatusBadge(booking.status)}>{booking.status}</span></div><div style={styles.bookingDetails}><span>📅 {new Date(booking.bookingDate).toLocaleDateString()}</span><span>⏰ {booking.bookingTime}</span><span>💰 ${booking.totalAmount}</span>{booking.isConcierge && <span>🚗 Concierge - Pickup: {booking.pickupAddress}</span>}</div>{booking.status === 'pending' && (<div style={styles.bookingActions}><button style={styles.confirmBtn} onClick={() => updateBookingStatus(booking._id, 'confirmed')}>✓ Confirm</button><button style={styles.rejectBtn} onClick={() => updateBookingStatus(booking._id, 'cancelled')}>✗ Reject</button></div>)}{booking.status === 'confirmed' && (<button style={styles.startBtn} onClick={() => updateBookingStatus(booking._id, 'in-progress')}>▶ Start Service</button>)}{booking.status === 'in-progress' && (<button style={styles.completeBtn} onClick={() => updateBookingStatus(booking._id, 'completed')}>✅ Complete</button>)}</div>))}</div>
            )}

            {activeTab === 'earnings' && (
              <div>
                {yourEarnings > 0 && firstPaymentId && (
                  <div style={styles.invoiceBanner}>
                    <div><strong>📄 Your Invoice is Ready!</strong><div style={{ fontSize: '12px', color: '#065f46' }}>Download your payment invoice</div></div>
                    <button onClick={() => downloadInvoice(firstPaymentId)} style={styles.downloadInvoiceBtn}>📄 Download Invoice (${yourEarnings})</button>
                  </div>
                )}

                <div style={styles.earningsSummary}>
                  <h2>💰 Earnings & Payouts</h2>
                  <div style={styles.earningsGrid}>
                    <div style={styles.earningsCard}><h3>Total Revenue</h3><p>${totalRevenue.toLocaleString()}</p><small>From {completedBookings} bookings</small></div>
                    <div style={styles.earningsCard}><h3>Your Earnings</h3><p style={{ color: '#10b981' }}>${yourEarnings.toLocaleString()}</p><small>70% of revenue</small></div>
                    <div style={styles.earningsCard}><h3>Platform Fee</h3><p style={{ color: '#f59e0b' }}>${platformFees.toLocaleString()}</p><small>15% commission</small></div>
                  </div>
                </div>

                <div style={styles.pendingSection}>
                  <h3>💸 Pending Payout</h3>
                  <div style={styles.pendingCard}>
                    <div><span style={styles.pendingAmount}>${pendingPayoutAmount.toLocaleString()}</span><span>pending for {pendingPayoutCount} booking{pendingPayoutCount !== 1 ? 's' : ''}</span></div>
                    <button style={styles.payoutBtnLarge} onClick={() => setShowPayoutModal(true)}>Request Payout</button>
                  </div>
                </div>

                <div style={styles.card}>
                  <h3>📋 Payout History</h3>
                  {loadingPayouts ? <div>Loading...</div> : payoutHistory.map(payout => (
                    <div key={payout._id} style={styles.payoutItem}>
                      <div><strong>{payout._id}</strong><div style={styles.payoutDate}>{new Date(payout.date).toLocaleDateString()}</div></div>
                      <div><span style={styles.payoutAmount}>${payout.amount.toLocaleString()}</span><div style={styles.payoutCount}>{payout.count} bookings</div></div>
                      <button onClick={() => downloadInvoice(payout._id)} style={styles.smallInvoiceBtn}>📄 Invoice</button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {activeTab === 'profile' && (
              <div style={styles.profileContainer}>
                <h2>👤 Business Profile</h2>
                <div style={styles.profileCard}><img src={businessProfile.logo} alt="logo" style={styles.avatarLarge} /><div style={styles.profileInfo}><div><strong>Business Name:</strong> {businessProfile.businessName}</div><div><strong>Owner:</strong> {businessProfile.ownerName}</div><div><strong>Email:</strong> {businessProfile.email}</div><div><strong>Phone:</strong> {businessProfile.phone}</div><div><strong>Address:</strong> {businessProfile.address || 'Not set'}</div><div><strong>Tax ID:</strong> {businessProfile.taxId || 'Not set'}</div></div><button style={styles.editProfileBtn} onClick={() => setShowEditProfileModal(true)}>✏️ Edit Profile</button></div>
                <div style={styles.bankSection}><h3>🏦 Payout Information</h3>{hasBankAccount ? (<div style={styles.bankCard}><div><strong>Account Holder:</strong> {bankAccount.accountName}</div><div><strong>Account Number:</strong> ••••{bankAccount.accountNumber?.slice(-4)}</div><div><strong>Bank Name:</strong> {bankAccount.bankName}</div><button style={styles.editBankBtn} onClick={() => setShowBankModal(true)}>Update</button><button style={styles.deleteBankBtn} onClick={deleteBankAccount}>Remove</button></div>) : (<div style={styles.noBankCard}><button style={styles.addBankBtn} onClick={() => setShowBankModal(true)}>+ Add Bank Account</button></div>)}</div>
                <div style={styles.stripeSection}><h3>💳 Automatic Payouts (Stripe Connect)</h3>{stripeStatus?.onboardingComplete ? (<div style={styles.stripeSuccessCard}><span>✅</span><div><strong>Stripe Connected!</strong><p>Your account is ready to receive automatic payouts.</p><button onClick={disconnectStripe} style={styles.disconnectStripeBtn}>Disconnect Stripe</button></div></div>) : stripeStatus?.hasAccount ? (<div style={styles.stripePendingCard}><span>⏳</span><div><strong>Stripe Account Pending</strong><p>Please complete the onboarding process.</p><button onClick={connectStripe} disabled={loadingStripe} style={styles.connectStripeBtn}>{loadingStripe ? 'Redirecting...' : 'Complete Setup →'}</button></div></div>) : (<div style={styles.stripeCard}><span>💰</span><div><strong>Get Paid Automatically</strong><p>Connect your Stripe account to receive automatic payouts.</p><button onClick={connectStripe} disabled={loadingStripe} style={styles.connectStripeBtn}>{loadingStripe ? 'Redirecting...' : 'Connect Stripe Account →'}</button></div></div>)}</div>
              </div>
            )}

            {activeTab === 'settings' && (
              <div style={styles.settingsContainer}>
                <h2>⚙️ Settings</h2>
                <div style={styles.settingsSection}><h3>🔔 Notification Preferences</h3><label><input type="checkbox" checked={settings.emailNotifications} onChange={(e) => setSettings({...settings, emailNotifications: e.target.checked})} /> Email</label><label><input type="checkbox" checked={settings.pushNotifications} onChange={(e) => setSettings({...settings, pushNotifications: e.target.checked})} /> Push</label></div>
                <button style={styles.saveSettingsBtn} onClick={() => toast.success('Settings saved!')}>Save</button>
              </div>
            )}
          </>
        )}
      </div>

      {/* Modals */}
      {showServiceModal && (<div style={styles.modal}><div style={styles.modalContent}><h2>{editingService ? 'Edit Service' : 'Add Service'}</h2><form onSubmit={handleServiceSubmit}><input style={styles.input} placeholder="Service Name" value={serviceForm.name} onChange={(e) => setServiceForm({...serviceForm, name: e.target.value})} required /><textarea style={styles.textarea} placeholder="Description" value={serviceForm.description} onChange={(e) => setServiceForm({...serviceForm, description: e.target.value})} required /><select style={styles.input} value={serviceForm.category} onChange={(e) => setServiceForm({...serviceForm, category: e.target.value})}>{categories.map(c => <option key={c.id} value={c.id}>{c.icon} {c.name}</option>)}</select><input type="number" style={styles.input} placeholder="Price ($)" value={serviceForm.price} onChange={(e) => setServiceForm({...serviceForm, price: e.target.value})} required /><input type="number" style={styles.input} placeholder="Duration (minutes)" value={serviceForm.duration} onChange={(e) => setServiceForm({...serviceForm, duration: e.target.value})} required /><input type="text" style={styles.input} placeholder="Tags (comma separated)" value={serviceForm.tags} onChange={(e) => setServiceForm({...serviceForm, tags: e.target.value})} /><div style={{ display: 'flex', gap: '10px', marginTop: '20px' }}><button type="submit" style={styles.submitBtn}>Save</button><button type="button" style={styles.cancelBtn} onClick={() => setShowServiceModal(false)}>Cancel</button></div></form></div></div>)}

      {showPayoutModal && (<div style={styles.modal}><div style={styles.modalContentSmall}><h2>Request Payout</h2><p>Available: ${pendingPayoutAmount}</p><input type="number" style={styles.input} placeholder="Amount" value={payoutAmount} onChange={(e) => setPayoutAmount(e.target.value)} /><div style={{ display: 'flex', gap: '10px', marginTop: '20px' }}><button onClick={requestPayout} style={styles.submitBtn}>Submit</button><button onClick={() => setShowPayoutModal(false)} style={styles.cancelBtn}>Cancel</button></div></div></div>)}

      {showEditProfileModal && (<div style={styles.modal}><div style={styles.modalContent}><h2>Edit Profile</h2><form onSubmit={updateProfile}><input style={styles.input} placeholder="Business Name" value={editProfileData.businessName} onChange={(e) => setEditProfileData({...editProfileData, businessName: e.target.value})} required /><input style={styles.input} placeholder="Phone" value={editProfileData.phone} onChange={(e) => setEditProfileData({...editProfileData, phone: e.target.value})} required /><input style={styles.input} placeholder="Address" value={editProfileData.address} onChange={(e) => setEditProfileData({...editProfileData, address: e.target.value})} /><div style={{ display: 'flex', gap: '10px', marginTop: '20px' }}><button type="submit" style={styles.submitBtn}>Save</button><button type="button" style={styles.cancelBtn} onClick={() => setShowEditProfileModal(false)}>Cancel</button></div></form></div></div>)}

      {showBankModal && (<div style={styles.modal}><div style={styles.modalContent}><h2>Bank Account</h2><form onSubmit={saveBankAccount}><input style={styles.input} placeholder="Account Holder Name" value={bankAccount.accountName} onChange={(e) => setBankAccount({...bankAccount, accountName: e.target.value})} required /><input style={styles.input} placeholder="Account Number" value={bankAccount.accountNumber} onChange={(e) => setBankAccount({...bankAccount, accountNumber: e.target.value})} required /><input style={styles.input} placeholder="Bank Name" value={bankAccount.bankName} onChange={(e) => setBankAccount({...bankAccount, bankName: e.target.value})} required /><input style={styles.input} placeholder="Routing Number" value={bankAccount.routingNumber} onChange={(e) => setBankAccount({...bankAccount, routingNumber: e.target.value})} required /><div style={{ display: 'flex', gap: '10px', marginTop: '20px' }}><button type="submit" style={styles.submitBtn} disabled={loadingBank}>Save</button><button type="button" style={styles.cancelBtn} onClick={() => setShowBankModal(false)}>Cancel</button></div></form></div></div>)}
    </div>
  );
}

